403	      /* reason 在 payload[3]：0x13 对端断开，0x16 本机主机，0x08 超时。 */
404	      syslog(LOG_INFO,
405	             "sf32lb52 bth4 disconn hdl=0x%02x%02x status=%02x reason=0x%02x\n",
406	             len > 5 ? data[5] : 0xff,
407	             len > 4 ? data[4] : 0xff,
408	             data[3],
409	             len > 6 ? data[6] : 0xff);
410	      /* 诊断：断开时把这条连接的完整画像打出来。0x13 是对端主动断开，
411	       * 配合下面的收发量能区分"对端重试"与"链路故障"。 */
412	      syslog(LOG_INFO,
413	             "sf32lb52 bth4 sess hdl=0x%04x conn#%u dur=%u ms "
414	             "acl_in=%lu/%luB acl_out=%lu/%luB evt_rx=%lu fwd_fail=%lu "
415	             "conn_upd=%lu\n",
416	             (unsigned)g_diag_conn_hdl, (unsigned)g_diag_conn_n,
417	             g_diag_conn_ms != 0
418	               ? (unsigned)myvendor_mono_elapsed_ms(myvendor_mono_ms(),
419	                                                   g_diag_conn_ms)
420	               : 0u,
421	             (unsigned long)g_diag_acl_in_pkts,
422	             (unsigned long)g_diag_acl_in_bytes,
423	             (unsigned long)g_diag_acl_out_pkts,
424	             (unsigned long)g_diag_acl_out_bytes,
425	             (unsigned long)g_diag_evt_rx,
426	             (unsigned long)g_diag_fwd_fail,
427	             (unsigned long)g_diag_conn_upd);
428	      g_diag_conn_ms = 0;
429	    }
430	  else if (data[1] == BT_HCI_EVT_LE_META_EVENT && data[2] >= 1 && len > 3)
431	    {
432	      /* 诊断：把 LE Meta 子事件解码成可读一行。原来只打 subevent 和三字节，
433	       * 看不到协商到的 interval/latency/timeout，也无法判断
434	       * Connection Update 为什么反复发生。
435	       *
436	       * 偏移约定：data[0]=H4 类型，data[1]=事件码，data[2]=plen，
437	       * data[3+n] = payload[n]。故 data[3] 是 subevent。
438	       * 子事件编号与 payload 长度见 Bluetooth Core Vol 4 Part E 7.7.65。
439	       */
440	      const uint8_t sub = data[3];
441	
442	      switch (sub)
443	        {
444	          case 0x01: /* LE Connection Complete, plen 19 */
445	            if (data[2] >= 19)
446	              {
447	                g_diag_conn_n++;
448	                g_diag_conn_hdl = sf32lb52_bt_get_le16(&data[5]);
449	                g_diag_acl_in_pkts = 0;
450	                g_diag_acl_in_bytes = 0;
451	                g_diag_acl_out_pkts = 0;
452	                g_diag_acl_out_bytes = 0;
453	                g_diag_evt_rx = 0;
454	                g_diag_fwd_fail = 0;
455	                g_diag_conn_upd = 0;
456	                g_diag_conn_ms = myvendor_mono_ms();
457	                syslog(LOG_INFO,
458	                       "sf32lb52 bth4 conn st=%02x hdl=0x%04x role=%u "
459	                       "atype=%u peer=%02x:%02x:%02x:%02x:%02x:%02x "
460	                       "itv=%u lat=%u to=%u(%u ms)\n",
461	                       data[4], (unsigned)g_diag_conn_hdl, data[7], data[8],
462	                       data[14], data[13], data[12], data[11], data[10], data[9],
463	                       (unsigned)sf32lb52_bt_get_le16(&data[15]),
464	                       (unsigned)sf32lb52_bt_get_le16(&data[17]),
465	                       (unsigned)sf32lb52_bt_get_le16(&data[19]),
466	                       (unsigned)(sf32lb52_bt_get_le16(&data[19]) * 10u));
467	              }
468	            break;
469	
470	          case 0x03: /* LE Connection Update Complete, plen 10 */
471	            if (data[2] >= 10)
472	              {
473	                uint16_t itv = sf32lb52_bt_get_le16(&data[7]);
474	
475	                g_diag_conn_upd++;
476	                syslog(LOG_INFO,
477	                       "sf32lb52 bth4 conn_upd#%lu st=%02x hdl=0x%04x "
478	                       "itv=%u(%u.%02u ms) lat=%u to=%u(%u ms)\n",
479	                       (unsigned long)g_diag_conn_upd, data[4],
480	                       (unsigned)sf32lb52_bt_get_le16(&data[5]),
481	                       (unsigned)itv,
482	                       (unsigned)((itv * 125u) / 100u),
483	                       (unsigned)((itv * 125u) % 100u),
484	                       (unsigned)sf32lb52_bt_get_le16(&data[9]),
485	                       (unsigned)sf32lb52_bt_get_le16(&data[11]),
486	                       (unsigned)(sf32lb52_bt_get_le16(&data[11]) * 10u));
487	              }
488	            break;
489	
490	          case 0x04: /* LE Read Remote Features Complete, plen 12 */
491	            if (data[2] >= 12)
492	              {
493	                syslog(LOG_INFO,
494	                       "sf32lb52 bth4 rmt_feat st=%02x hdl=0x%04x "
495	                       "feat=%02x%02x%02x%02x%02x%02x%02x%02x\n",
496	                       data[4], (unsigned)sf32lb52_bt_get_le16(&data[5]),
497	                       data[14], data[13], data[12], data[11],
498	                       data[10], data[9], data[8], data[7]);
499	              }
500	            break;
501	
502	          case 0x07: /* LE Data Length Change, plen 11 */
503	            if (data[2] >= 11)
504	              {
505	                syslog(LOG_INFO,
506	                       "sf32lb52 bth4 dlen hdl=0x%04x tx=%u/%u rx=%u/%u\n",
507	                       (unsigned)sf32lb52_bt_get_le16(&data[3]),
508	                       (unsigned)sf32lb52_bt_get_le16(&data[5]),
509	                       (unsigned)sf32lb52_bt_get_le16(&data[7]),
510	                       (unsigned)sf32lb52_bt_get_le16(&data[9]),
511	                       (unsigned)sf32lb52_bt_get_le16(&data[11]));
512	              }
513	            break;
514	
515	          default:
516	            /* 保留原来的兜底行，避免丢失信息。 */
517	            syslog(LOG_INFO,
518	                   "sf32lb52 bth4 evt=0x%02x le_sub=0x%02x len=%u "
519	                   "p1=%02x p2=%02x\n",
520	                   data[1], sub, data[2],
521	                   len > 4 ? data[4] : 0xff,
522	                   len > 5 ? data[5] : 0xff);
523	            break;
524	        }
525	    }
526	  else if (data[1] != BT_HCI_EVT_NUM_COMPLETED_PACKETS)
527	    {
528	      syslog(LOG_INFO,
529	             "sf32lb52 bth4 evt=0x%02x len=%u p0=%02x p1=%02x p2=%02x\n",
530	             data[1], data[2],
531	             len > 3 ? data[3] : 0xff,
532	             len > 4 ? data[4] : 0xff,
533	             len > 5 ? data[5] : 0xff);
534	    }
535	}
