537	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
538	                                      uint8_t *data, size_t len)
539	{
540	  enum bt_buf_type_e type;
541	  int ret;
542	
543	  if (len <= H4_HEADER_SIZE)
544	    {
545	      return -EINVAL;
546	    }
547	
548	  switch (data[0])
549	    {
550	      case H4_EVT:
551	        sf32lb52_bt_normalize_event(data, len);
552	        g_diag_evt_rx++;
553	        type = BT_EVT;
554	        break;
555	
556	      case H4_ACL:
557	        g_diag_acl_in_pkts++;
558	        g_diag_acl_in_bytes += (uint32_t)len;
559	        type = BT_ACL_IN;
560	        break;
561	
562	      case H4_ISO:
563	        type = BT_ISO_IN;
564	        break;
565	
566	      case H4_SCO:
567	        /* NuttX bt_buf has no SCO type.  Consume the packet so the H4
568	         * stream stays aligned; page scan does not need voice slots.
569	         */
570	        syslog(LOG_INFO, "sf32lb52 bth4 drop sco len=%lu\n",
571	               (unsigned long)len);
572	        return OK;
573	
574	      default:
575	        return -EINVAL;
576	    }
577	
578	  ret = bt_netdev_receive(&priv->drv,
579	                          type,
580	                          (void *)&data[H4_HEADER_SIZE],
581	                          len - H4_HEADER_SIZE);
582	  if (ret < 0)
583	    {
584	      /* 诊断：这里是 HCI 包被永久丢弃的唯一出口。丢一个 ACL 分片会让
585	       * L2CAP 重组永不完结，丢一个断连事件会让上层一直以为链路还在。
586	       * 计数 + 类型是判断"上层看到的蓝牙异常是否源于此处"的关键。 */
587	      g_diag_fwd_fail++;
588	      syslog(LOG_ERR,
589	             "sf32lb52 bth4 fwd fail n=%lu type=0x%02x len=%lu ret=%d "
590	             "(pkt dropped)\n",
591	             (unsigned long)g_diag_fwd_fail, data[0],
592	             (unsigned long)len, ret);
593	      wlerr("Failed to receive HCI packet: %d\n", ret);
594	    }
595	
596	  return ret;
597	}
