599	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
600	                                          uint16_t opcode,
601	                                          const uint8_t *return_params,
602	                                          size_t return_len)
603	{
604	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
605	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
606	  size_t payload_len;
607	
608	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
609	    {
610	      return -E2BIG;
611	    }
612	
613	  payload_len = 3 + return_len;
614	  event[0] = H4_EVT;
615	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
616	  event[2] = payload_len;
617	  event[3] = 1;
618	  sf32lb52_bt_put_le16(&event[4], opcode);
619	  if (return_len > 0)
620	    {
621	      memcpy(&event[6], return_params, return_len);
622	    }
623	
624	  return sf32lb52_bt_forward_packet(priv, event,
625	                                    H4_HEADER_SIZE +
626	                                    sizeof(struct bt_hci_evt_hdr_s) +
627	                                    payload_len);
628	}
