extern "C" {
#endif

#define MYVENDOR_SCHEDMON_NAME  12
#define MYVENDOR_SCHEDMON_TASKS 24
#define MYVENDOR_SCHEDMON_NULL  4

struct myvendor_schedmon_task_s
{
  int16_t pid;
  int16_t pri;
  int16_t lockcount;
  uint8_t state;
  uint8_t waitdog;
  uintptr_t waitobj;
  char name[MYVENDOR_SCHEDMON_NAME];
