struct myvendor_schedmon_null_s
{
  uint32_t seq;
  uint32_t ticks;
  uint32_t ipsr;
  int16_t wt_pid;
  int16_t run_pid;
  int16_t wt_pri;
  int16_t run_lock;
  int16_t errcode;
  uint8_t wt_state;
  uint8_t run_state;
  char wt_name[MYVENDOR_SCHEDMON_NAME];
  char run_name[MYVENDOR_SCHEDMON_NAME];
  /** @brief waitirq_bad 用：NXSEM_COUNT / NXSEM_MHOLDER 的不变量原值。 */
  int32_t value;
  /** @brief waitirq_bad 用：非 0 表示走的是 mutex 不变量。 */
  uint8_t bad_mutex;
  uint8_t pad_[3];
