  if (slot->sub_step == 1)
    {
      if (slot_try_subscribe_bat(slot))
        {
          return;
        }

      slot->sub_step = 2;
    }

  if (!slot->meas_sub_ok)
    {
      LOGE("%s meas CCC not armed", kind_name(slot->kind));
      slot->drop_link = true;
      return;
    }

  slot_read_loc(slot);
  if (slot->bat_h != 0)
    {
      (void)bt_gattc_read(slot->gatt, slot->bat_h);
    }

  slot_finish_ready(slot);
