       (unsigned)idx, kinds, addr, (int)found->rssi, kind_name(target));

  /** 一个地址一个 GATTC：只绑上面定下来的那一个 kind。 */
  for (kind = 0; kind < SENSOR_KIND_COUNT; kind++)
