static bool send_tx(void)
{
  uint8_t      frame[FS_STAGING_MAX];
  bt_status_t  ret;
  uint8_t      flags = 0;

  if (g_fs.handle == NULL || !g_fs.connected || !g_fs.ccc)
    {
      return false;
    }

  if (g_fs.tx_last)
    {
      flags |= COMPANION_FS_FLAG_LAST;
    }

  if (g_fs.tx_err)
    {
      flags |= COMPANION_FS_FLAG_ERR;
    }

  frame[0] = g_fs.cmd;
  frame[1] = g_fs.tid;
  frame[2] = flags;
  frame[3] = g_fs.tx_status;
  put_le16(frame + 4, g_fs.seq);
  put_le16(frame + 6, g_fs.tx_len);
  if (g_fs.tx_len > 0)
    {
      memcpy(frame + COMPANION_FS_HDR_LEN, g_fs.tx, g_fs.tx_len);
    }

  ret = bt_gatts_notify(g_fs.handle, &g_fs.peer, g_fs.data_attr,
                        frame, (uint16_t)(COMPANION_FS_HDR_LEN + g_fs.tx_len));
  if (ret != BT_STATUS_SUCCESS)
    {
      g_diag_notify_fail++;
      LOGE("fs notify failed: %d", (int)ret);
      return false;
    }

  g_diag_notify_sent++;

  if (g_fs.inflight < 255)
    {
      g_fs.inflight++;
    }

  g_fs.send_ms = fs_now_ms();
  g_fs.seq++;
  g_fs.tx_len = 0;
  if (g_fs.tx_last && g_fs.state != FS_WRITE)
    {
      g_fs.state = FS_IDLE;
    }

  g_fs.tx_last = false;
  g_fs.tx_err  = false;
  return true;
}

