/* 把 v 按固定位数（零填充）写进 p，返回新的写指针。v 超出位数时按低位截断。 */

static char *diaglog_put_u(char *p, unsigned v, unsigned width)
{
  unsigned i;

  for (i = 0; i < width; i++)
    {
      unsigned digit = v;
      unsigned j;

      /* 第 i 位 = v / 10^(width-1-i) 的个位；不用除法表，固定次数循环取。 */
      for (j = 0; j < (width - 1u - i); j++)
        {
          digit /= 10u;
        }

      p[i] = (char)('0' + (digit % 10u));
    }

  return p + width;
}

